SUPABASE_PASS = os.environ.get("SUPABASE_PASS", "#Paresh@7359")

USE_PSYCOPG2 = False
try:
    import psycopg2
    from psycopg2.extras import RealDictCursor
    USE_PSYCOPG2 = True
except Exception:
    import pg8000.dbapi

class DBWrapper:
    def __init__(self):
        candidates = [
            {
                "host": SUPABASE_HOST,
                "port": SUPABASE_PORT,
                "database": SUPABASE_DB,
                "user": SUPABASE_USER,
                "password": SUPABASE_PASS
            },
            {
                "host": "aws-0-ap-south-1.pooler.supabase.com",
                "port": 6543,
                "database": "postgres",
                "user": "postgres.oemmhemsmhtlkdasvdjy",
                "password": SUPABASE_PASS
            },
            {
                "host": "db.oemmhemsmhtlkdasvdjy.supabase.co",
                "port": 5432,
                "database": "postgres",
                "user": "postgres",
                "password": SUPABASE_PASS
            }
        ]

        self.conn = None
        self.driver = None

        for c in candidates:
            if USE_PSYCOPG2:
                try:
                    self.conn = psycopg2.connect(
                        host=c["host"],
                        port=c["port"],
                        dbname=c["database"],
                        user=c["user"],
                        password=c["password"],
                        connect_timeout=6,
                        cursor_factory=RealDictCursor
                    )
                    self.cur = self.conn.cursor()
                    self.driver = "psycopg2"
                    break
                except Exception:
                    pass

            if not self.conn:
                try:
                    import pg8000.dbapi
                    self.conn = pg8000.dbapi.connect(
                        host=c["host"],
                        port=c["port"],
                        database=c["database"],
                        user=c["user"],
                        password=c["password"],
                        timeout=6
                    )
                    self.cur = self.conn.cursor()
                    self.driver = "pg8000"
                    break
                except Exception:
                    pass

        if not self.conn:
            raise Exception("Could not connect to Supabase PostgreSQL database.")

    def execute(self, sql, params=None):
        if params is not None:
            self.cur.execute(sql, tuple(params))
        else:
            self.cur.execute(sql)

    def fetchall(self):
        rows = self.cur.fetchall()
        if not rows:
            return []
        if self.driver == "psycopg2":
            return [dict(r) for r in rows]
        else:
            cols = [d[0] for d in self.cur.description]
            return [dict(zip(cols, r)) for r in rows]

    def fetchone(self):
        r = self.cur.fetchone()
        if not r:
            return None
        if self.driver == "psycopg2":
            return dict(r)
        else:
            cols = [d[0] for d in self.cur.description]
            return dict(zip(cols, r))

    def commit(self):
        self.conn.commit()

    def rollback(self):
        self.conn.rollback()

    def close(self):
        try:
            self.cur.close()
            self.conn.close()
        except Exception:
            pass

def get_db():
    return DBWrapper()

def load_template_text(name, fallback_text):
    paths = [
        os.path.join(BASE_DIR, 'templates', name),
        os.path.join(BASE_DIR, name),
        os.path.join(os.getcwd(), 'templates', name),
        os.path.join(os.getcwd(), name),
    ]
    for p in paths:
        if os.path.exists(p):
            try:
                with open(p, 'r', encoding='utf-8') as f:
                    return f.read()
            except Exception:
                pass
    return fallback_text

